mapper.update:
UPDATE tdm40_manl_job
   SET tdm40_reg_date              = #{regDate}
     , tdm40_job_nm                = #{jobName}
     , tdm40_manl_apply_start_date = #{manlApplyStartDate}
     , tdm40_role_id               = #{roleId}
     , tdm40_org_id                = #{orgId}
     , tdm40_job_reason            = #{jobReason}
     , tdm40_start_date            = #{startDate}
     , tdm40_end_date              = #{endDate}
     , tdm40_upd_nm                = #{updName}
     , tdm40_upd_date              = f_sysdate()
 WHERE tdm40_manl_job_id = #{manlJobId}
   AND tdm40_company_id  = #{companyId}

