#{manlJobId}

mapper.insert:
INSERT INTO tdm41_manl_duty SELECT f_create_seq() , #{manlJobId} , tdm30_role_id , tdm35_task_id , tdm35_task_relate_detail_id , tdm35_task_relate_duty_id , #{updName} , f_sysdate() , #{companyId} FROM ( SELECT * FROM getTdm30RoleAllc(#{companyId}, CAST(#{manlApplyStartDate} AS date), true) INNER JOIN tdm35_role_allc_task ON tdm35_role_allc_detail_id = tdm30_role_allc_detail_id WHERE 1=1
AND tdm30_role_id = #{roleId}
ORDER BY tdm30_role_id, tdm35_task_id, tdm35_task_relate_detail_seq, tdm35_task_relate_duty_seq ) t
